1	import type {
2		GameHistoryListResult,
3		GameHistoryRepository,
4	} from "../../domain/game/ports/GameHistoryRepository";
5	import type { GameItemSelectionService } from "../../domain/game/services/GameItemSelectionService";
6	import type {
7		GameHistoryEntry,
8		GameItem,
9		GameRatingRecord,
10		GameRoundConfig,
11		GameRoundSummary,
12		RandomSource,
13	} from "../../domain/game/types";
14	import type { RecallRating } from "../../domain/shared/types";
15	
16	const ALL_RATINGS: readonly RecallRating[] = [1, 2, 3, 4, 5];
17	
18	/** Ratings counting as "recalled" toward accuracy — Good and Easy only. */
19	const CORRECT_RATINGS: ReadonlySet<RecallRating> = new Set([4, 5]);
20	
21	/**
22	 * The item's identity: a `symbolCharacter` for a symbol item, a `thaiWord`
23	 * for a word item — matches the dedupe key each `GameItemSource` uses (see
24	 * CONTEXT.md, GameRatingRecord's `itemKey` doc comment).
25	 */
26	function itemKeyOf(item: GameItem): string {
27		return item.kind === "symbol" ? item.symbolCharacter : item.thaiWord;
28	}
29	
30	/**
31	 * A round's ratings, as recorded so far. Every function here is a pure
32	 * function of the arguments it is given — no round-in-progress state ever
33	 * lives on this class, matching `ConductReviewUseCase`/`ReviewService`'s own
34	 * caller-holds-the-session convention (see CONTEXT.md). `AppContext.tsx`
35	 * wires this up as one long-lived singleton; a singleton holding mutable
36	 * per-round state would leak ratings between rounds and between mounts.
37	 *
38	 * No `CardRepository` is ever received here — only `GameItemSelectionService`
39	 * (which wraps it) and `GameHistoryRepository`. There is therefore no code
40	 * path through this use case that could ever call `CardRepository.save` or
41	 * `ReviewableCard.recordReview`: the SRS-isolation guarantee is structural,
42	 * not merely a rule nobody happens to break.
43	 */
44	export class PlayGameUseCase {
45		/**
46		 * Tracks which `GameRoundSummary` objects have already been persisted, so
47		 * that finishing/saving the same completed round twice (a duplicate
48		 * effect run, a duplicate button press) does not append a duplicate
49		 * history entry. Keyed by object identity, not content: two genuinely
50		 * distinct rounds that happen to produce an identical summary are still
51		 * two history entries. A `WeakSet` holds no strong reference, so it
52		 * never keeps a finished round's data alive past the caller's own use of
53		 * it — this is bookkeeping for `saveHistory`'s own idempotency, not
54		 * round-in-progress state.
55		 */
56		private readonly savedSummaries = new WeakSet<GameRoundSummary>();
57	
58		constructor(
59			private readonly selectionService: GameItemSelectionService,
60			private readonly historyRepository: GameHistoryRepository,
61		) {}
62	
63		startRound(config: GameRoundConfig, rng?: RandomSource): GameItem[] {
64			return this.selectionService.selectRound(config, rng);
65		}
66	
67		/**
68		 * Returns a new ratings array with `itemIndex`'s rating set to `rating`,
69		 * overwriting any prior rating for that same index rather than appending
70		 * a second record for it — recording twice for one item (a stray global
71		 * keypress landing on top of a click, see CONTEXT.md) must not double-
72		 * count that item in the finished summary.
73		 */
74		recordRating(
75			items: readonly GameItem[],
76			ratings: readonly GameRatingRecord[],
77			itemIndex: number,
78			rating: RecallRating,
79		): GameRatingRecord[] {
80			const item = items[itemIndex];
81			if (!item) return [...ratings];
82	
83			const itemKey = itemKeyOf(item);
84			const record: GameRatingRecord = {
85				itemKey,
86				kind: item.kind,
87				challengeDirection: item.challengeDirection,
88				rating,
89			};
90	
91			return [...ratings.filter((r) => r.itemKey !== itemKey), record];
92		}
93	
94		/**
95		 * `accuracy` counts only ratings 4 (Good) and 5 (Easy) as correct — a
96		 * deliberately different, stricter threshold from
97		 * `ReviewService.endReviewSession`'s `rating >= 3`, and rounded half-up.
98		 * `null` if and only if no rating was recorded, distinct from a rated
99		 * round where none of the ratings were Good/Easy (`accuracy: 0`).
100		 */
101		finishRound(ratings: readonly GameRatingRecord[]): GameRoundSummary {
102			const ratingCounts = ALL_RATINGS.reduce(
103				(counts, value) => {
104					counts[value] = ratings.filter((r) => r.rating === value).length;
105					return counts;
106				},
107				{} as Record<RecallRating, number>,
108			);
109	
110			const ratedCount = ratings.length;
111			const correctCount = ratings.filter((r) =>
112				CORRECT_RATINGS.has(r.rating),
113			).length;
114			const accuracy =
115				ratedCount === 0 ? null : Math.round((correctCount / ratedCount) * 100);
116	
117			return { ratingCounts, ratedCount, accuracy };
118		}
119	
120		saveHistory(
121			config: Pick<GameRoundConfig, "pools" | "itemCount">,
122			summary: GameRoundSummary,
123		): void {
124			if (this.savedSummaries.has(summary)) return;
125			this.savedSummaries.add(summary);
126	
127			const entry: GameHistoryEntry = {
128				id: crypto.randomUUID(),
129				playedAt: new Date().toISOString(),
130				pools: config.pools,
131				itemCount: config.itemCount,
132				summary,
133			};
134			this.historyRepository.save(entry);
135		}
136	
137		getHistory(): GameHistoryListResult {
138			return this.historyRepository.list();
139		}
140	}
