1	import { useCallback, useMemo, useRef, useState } from "react";
2	import { useNavigate } from "react-router";
3	import { Button } from "@/presentation/components/ui/button";
4	import type { PlayGameUseCase } from "../../application/use-cases/PlayGameUseCase";
5	import type {
6		GameInputMode,
7		GameItem,
8		GameRatingRecord,
9		GameRoundSummary as GameRoundSummaryData,
10	} from "../../domain/game/types";
11	import type { RecallRating } from "../../domain/shared/types";
12	import { SectionHeader } from "../components/atoms/SectionHeader";
13	import { GameHistoryList } from "../components/molecules/GameHistoryList";
14	import { GameRoundSummary } from "../components/organisms/GameRoundSummary";
15	import { SymbolDictationChallenge } from "../components/organisms/SymbolDictationChallenge";
16	import { SymbolReadingChallenge } from "../components/organisms/SymbolReadingChallenge";
17	import { useApp } from "../hooks/useApp";
18	
19	type GamePhase = "setup" | "playing" | "summary";
20	
21	/** Phase 1 practices symbols only; phase 2 adds the pool selector. */
22	const GAME_POOLS = ["script"] as const;
23	
24	const DEFAULT_ITEM_COUNT = 10;
25	
26	/**
27	 * Selection is a pure function, so asking for every item is a side-effect-
28	 * free way to learn how many are eligible — the use case exposes no
29	 * separate count query.
30	 */
31	function countEligibleItems(game: PlayGameUseCase): number {
32		return game.startRound({
33			pools: GAME_POOLS,
34			itemCount: Number.MAX_SAFE_INTEGER,
35			prioritizeWeakItems: false,
36			inputMode: "draw",
37		}).length;
38	}
39	
40	/**
41	 * A self-graded practice round over introduced symbols. The page owns all
42	 * round state (`items`/`ratings`/`currentIndex`) and threads it through
43	 * `PlayGameUseCase`'s pure functions — the use case is a long-lived
44	 * singleton and must never hold a round.
45	 *
46	 * Deliberately reads only `game` from `useApp()`: no `refresh()`, no
47	 * `checkAchievements`, nothing that could write the SRS blob. A practice
48	 * round must leave `thai-srs-state` byte-identical.
49	 */
50	export function GamePage() {
51		const { game } = useApp();
52		const navigate = useNavigate();
53	
54		const [phase, setPhase] = useState<GamePhase>("setup");
55		const [inputMode, setInputMode] = useState<GameInputMode>("draw");
56		const [items, setItems] = useState<GameItem[]>([]);
57		const [ratings, setRatings] = useState<GameRatingRecord[]>([]);
58		const [currentIndex, setCurrentIndex] = useState(0);
59		const [summary, setSummary] = useState<GameRoundSummaryData | null>(null);
60		// Guards against a rating landing twice for one item (a stray global
61		// keypress on top of a click) advancing past the next item unseen.
62		const ratedIndexRef = useRef(-1);
63	
64		const eligibleCount = useMemo(
65			() => (phase === "setup" ? countEligibleItems(game) : 0),
66			[game, phase],
67		);
68		const [countInput, setCountInput] = useState<string>(() =>
69			eligibleCount > 0
70				? String(Math.min(DEFAULT_ITEM_COUNT, eligibleCount))
71				: "",
72		);
73		const history = useMemo(
74			() => (phase === "setup" ? game.getHistory() : null),
75			[game, phase],
76		);
77	
78		// `Number("")` is 0, which the >= 1 rule already rejects.
79		const parsedCount = Number(countInput);
80		const countValid =
81			Number.isInteger(parsedCount) &&
82			parsedCount >= 1 &&
83			parsedCount <= eligibleCount;
84	
85		const handleStart = useCallback(() => {
86			const roundItems = game.startRound({
87				pools: GAME_POOLS,
88				itemCount: parsedCount,
89				prioritizeWeakItems: false,
90				inputMode,
91			});
92			if (roundItems.length === 0) return;
93			setItems(roundItems);
94			setRatings([]);
95			setCurrentIndex(0);
96			setSummary(null);
97			ratedIndexRef.current = -1;
98			setPhase("playing");
99		}, [game, parsedCount, inputMode]);
100	
101		const handleRate = useCallback(
102			(rating: RecallRating) => {
103				if (ratedIndexRef.current >= currentIndex) return;
104				ratedIndexRef.current = currentIndex;
105	
106				const nextRatings = game.recordRating(
107					items,
108					ratings,
109					currentIndex,
110					rating,
111				);
112				setRatings(nextRatings);
113	
114				if (currentIndex + 1 < items.length) {
115					setCurrentIndex(currentIndex + 1);
116					return;
117				}
118	
119				const roundSummary = game.finishRound(nextRatings);
120				game.saveHistory(
121					{ pools: GAME_POOLS, itemCount: items.length },
122					roundSummary,
123				);
124				setSummary(roundSummary);
125				setPhase("summary");
126			},
127			[game, items, ratings, currentIndex],
128		);
129	
130		if (phase === "playing") {
131			const item = items[currentIndex];
132			// `GAME_POOLS` is script-only until task 2.3 adds the pool selector, so
133			// a word item can never actually reach this page yet — this narrowing
