2	import { fireEvent, render, screen } from "@testing-library/react";
3	import { Link, MemoryRouter, Route, Routes } from "react-router";
4	import { describe, expect, it } from "vitest";
5	import type { GameHistoryEntry } from "../../domain/game/types";
6	import { InMemoryJsonStore } from "../../infrastructure/persistence/JsonStore";
7	import { AppProvider } from "../context/AppContext";
8	import {
9		CorruptJsonStore,
10		canvas2d,
11		createdAudioUrls,
12		getFakeLocalStorage,
13		makeFixedRoundGame,
14		makeGame,
15		makeHistoryEntry,
16		makeSymbolItem,
17		renderWithApp,
18	} from "../test-utils/renderWithApp";
19	import { Dashboard } from "./Dashboard";
20	import { GamePage } from "./GamePage";
21	
22	const CANVAS_NAME = "Drawing area for writing Thai characters";
23	
24	function reveal() {
25		fireEvent.click(screen.getByRole("button", { name: "Show Answer" }));
26	}
27	
28	function rate(label: RegExp) {
29		fireEvent.click(screen.getByRole("button", { name: label }));
30	}
31	
32	function setCount(value: string) {
33		fireEvent.change(screen.getByLabelText("Items per round"), {
34			target: { value },
35		});
36	}
37	
38	function startRound() {
39		fireEvent.click(screen.getByRole("button", { name: "Start Round" }));
40	}
41	
42	/** A raw `PropertyCard` DTO as it sits inside the persisted SRS blob. */
43	function scriptCardDTO(character: string) {
44		return {
45			id: `${character}-recognition`,
46			question: `What sound does ${character} make?`,
47			correctAnswer: "answer",
48			choices: ["answer", "other"],
49			srs: {
50				easeFactor: 2,
51				interval: 10,
52				repetitions: 0,
53				learningStep: 1,
54				nextReviewDate: "2026-01-01T00:00:00.000Z",
55				lastReviewDate: null,
56				lapseCount: 0,
57			},
58			symbolCharacter: character,
59			property: "recognition",
60			lessonNumber: 1,
61		};
62	}
63	
64	describe("GamePage", () => {
65		// AC1
66		it("presents exactly the configured number of item screens before the summary", () => {
67			renderWithApp(<GamePage />, {}, { symbols: ["ม", "น", "ง", "ย", "ว"] });
68			setCount("3");
69			startRound();
70	
71			let screensTraversed = 0;
72			while (
73				screen.queryByText("Round Complete") === null &&
74				screensTraversed < 10
75			) {
76				expect(screen.getByText(`${screensTraversed + 1} / 3`)).toBeTruthy();
77				reveal();
78				rate(/Good/);
79				screensTraversed += 1;
80			}
81	
82			expect(screensTraversed).toBe(3);
83			expect(screen.getByText("Round Complete")).toBeTruthy();
84		});
85	
86		// AC2
87		it("renders dictation with audio before reveal and reading with audio only after reveal", () => {
88			const dictation = makeSymbolItem("ม", "dictation", {
89				audioUrl: "/audio/mo-ma.mp3",
90				correctAnswer: "maaw maa",
91			});
92			const reading = makeSymbolItem("น", "reading", {
93				audioUrl: "/audio/no-nu.mp3",
94				correctAnswer: "naaw nuu",
95			});
96			const { game } = makeFixedRoundGame([dictation, reading]);
97			renderWithApp(<GamePage />, { game });
98			startRound();
99	
100			// Dictation: prompt audio is constructed up front, canvas is offered.
101			expect(createdAudioUrls()).toContain("/audio/mo-ma.mp3");
102			expect(screen.getByRole("img", { name: CANVAS_NAME })).toBeTruthy();
103			reveal();
104			expect(screen.getByText("maaw maa")).toBeTruthy();
105			rate(/Good/);
106	
107			// Reading: no audio constructed before its reveal...
108			expect(screen.getByText("น")).toBeTruthy();
109			expect(createdAudioUrls()).not.toContain("/audio/no-nu.mp3");
110			reveal();
111			// ...exactly one constructed by the reveal.
112			expect(
113				createdAudioUrls().filter((url) => url === "/audio/no-nu.mp3"),
114			).toHaveLength(1);
115			expect(screen.getByText("naaw nuu")).toBeTruthy();
116		});
117	
118		// AC2 (input-mode half)
119		it("dictation in paper mode renders no canvas and taps through to the reveal", () => {
120			const { game } = makeFixedRoundGame([makeSymbolItem("ม", "dictation")]);
121			renderWithApp(<GamePage />, { game });
122			fireEvent.click(screen.getByLabelText("Write on paper"));
123			startRound();
124	
125			expect(screen.queryByRole("img", { name: CANVAS_NAME })).toBeNull();
126			reveal();
127			expect(screen.getByRole("button", { name: /Good/ })).toBeTruthy();
128		});
129	
130		// AC3
131		it("shows rating buttons only after reveal and advances on rating", () => {
132			const { game } = makeFixedRoundGame([
133				makeSymbolItem("ม", "dictation"),
134				makeSymbolItem("น", "dictation"),
135			]);
136			renderWithApp(<GamePage />, { game });
137			startRound();
138	
139			expect(screen.getByText("1 / 2")).toBeTruthy();
140			expect(screen.queryByRole("button", { name: /Again/ })).toBeNull();
141			reveal();
142			expect(screen.getByRole("button", { name: /Again/ })).toBeTruthy();
143			rate(/Good/);
144	
145			expect(screen.getByText("2 / 2")).toBeTruthy();
146			reveal();
147			rate(/Easy/);
148			expect(screen.getByText("Round Complete")).toBeTruthy();
149		});
150	
151		// AC4 — the plan's end-to-end SRS-isolation proof, deliberately NOT using
152		// renderWithApp: the real AppProvider (module-level singletons and all)
153		// is the wiring a hand-built context double would bypass.
154		it("leaves the whole thai-srs-state blob byte-identical after a full round through the real AppProvider", () => {
155			const seeded = JSON.stringify({
156				completedLessons: [1],
157				currentLesson: 2,
158				cards: {
159					"ม-recognition": scriptCardDTO("ม"),
160					"น-recognition": scriptCardDTO("น"),
161					"ง-recognition": scriptCardDTO("ง"),
162				},
163				vocabCards: {},
164				grammarCards: {},
165				sentenceCards: {},
166				// Streak/achievement material lives in these fields — the whole
167				// blob must survive, not just card schedules.
168				sessionHistory: [
169					{
170						sessionId: "s-1",
171						completedAt: "2026-09-01T10:00:00.000Z",
172						type: "review",
173						durationMs: 60000,
174						totalCards: 5,
175						correctCount: 4,
176						incorrectCount: 1,
177						accuracy: 80,
178						newCardsGraduated: 1,
179					},
180				],
181				achievements: ["first-lesson"],
182			});
183			getFakeLocalStorage().setItem("thai-srs-state", seeded);
184	
185			render(
186				<AppProvider>
187					<MemoryRouter initialEntries={["/game"]}>
188						<Routes>
189							<Route path="/game" element={<GamePage />} />
190						</Routes>
191					</MemoryRouter>
192				</AppProvider>,
193			);
194	
195			setCount("3");
196			startRound();
197			for (const rating of [/Again/, /Good/, /Easy/]) {
198				reveal();
199				rate(rating);
200			}
201			expect(screen.getByText("Round Complete")).toBeTruthy();
202	
203			// The round itself persisted — to its own key...
204			expect(
205				getFakeLocalStorage().getItem("thai-srs-game-history"),
206			).not.toBeNull();
207			// ...while the whole SRS blob is byte-identical.
208			expect(getFakeLocalStorage().getItem("thai-srs-state")).toBe(seeded);
209		});
210	
211		// AC5
212		it("renders never-played history as its own message", () => {
213			renderWithApp(<GamePage />, {}, { symbols: ["ม"] });
214			expect(screen.getByText("No games played yet.")).toBeTruthy();
215			expect(screen.queryByText(/history is unavailable/i)).toBeNull();
216		});
217	
218		// AC5
219		it("renders stored history entries as a populated list", () => {
220			const historyStore = new InMemoryJsonStore<GameHistoryEntry[]>();
221			historyStore.save([makeHistoryEntry({ id: "e1", itemCount: 4 })]);
222			const game = makeGame({ symbols: ["ม"], historyStore });
223			renderWithApp(<GamePage />, { game });
224	
225			expect(screen.getByText("Symbols · 4 items")).toBeTruthy();
226			expect(screen.getByText("75%")).toBeTruthy();
227			expect(screen.queryByText("No games played yet.")).toBeNull();
228			expect(screen.queryByText(/history is unavailable/i)).toBeNull();
229		});
230	
231		// AC5
232		it("renders a corrupt history read as unavailable, never as never-played", () => {
233			const game = makeGame({
234				symbols: ["ม"],
235				historyStore: new CorruptJsonStore<GameHistoryEntry[]>(),
236			});
237			renderWithApp(<GamePage />, { game });
238	
239			expect(screen.getByText(/history is unavailable/i)).toBeTruthy();
240			expect(screen.queryByText("No games played yet.")).toBeNull();
241		});
242	
243		// AC6
244		it("keeps start unavailable and explains when no symbols are eligible", () => {
245			renderWithApp(<GamePage />);
246			expect(screen.getByText(/No symbols to practice yet/)).toBeTruthy();
247			expect(screen.queryByRole("button", { name: "Start Round" })).toBeNull();
248		});
249	
250		// AC7 — two consecutive same-direction items keep the same component
