/** Tolerates a `RandomSource` that strays outside `[0, 1)`. */
function roll(rng: RandomSource): number {
	const value = rng();
	if (!Number.isFinite(value)) return 0;
	return Math.min(Math.max(value, 0), 0.999999999);
}

